int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    const long long MOD = 1000000007;
    long long total = 1;
    long long last[26] = {0};
    for (char ch : s) {
        int i = ch - 'a';
        long long newTotal = ((2 * total - last[i]) % MOD + MOD) % MOD;
        last[i] = total;
        total = newTotal;
    }
    cout << ((total - 1) % MOD + MOD) % MOD << "\n";

    return 0;
}

